-- GENERATED by `wfj generate` from data/gossip/gossip-db.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["db0173c7ed122435"] = { "L'arte dell'arco è una grande risorsa per chiunque, non solo per il cacciatore. Puoi colpire in fretta, in silenzio, e prima che la tua preda possa battere ciglio... è morta.", "." },
  ["db07de6f48f76f40"] = { "<Quello/Quella> là, Malagan. <Lo/La> conosco. Affidabile, <coraggioso/coraggiosa> e <fidato/fidata>. Si chiama {name}.", "." },
  ["db08e469c674849a"] = { "Il popolo fu annientato per preservare la vita immortale e i poteri quasi illimitati del principe. Il potere un tempo diviso fra migliaia ora confluisce nel principe e nei fanatici Shen'dralar. I pochi sopravvissuti rimasti alimentano direttamente i piloni per tenere imprigionato Immol'thar.\n\nSe il demone dovesse liberarsi dai suoi vincoli, distruggerebbe di certo il poco che resta di questo bastione delle arti arcane, un tempo grandioso.", "." },
  ["db09ac455dce5596"] = { "%s si arrende.", "." },
  ["db0f2fc16062d3e1"] = { "Benvenut<o/a> alla gara di pesca della ⟦Booty Bay=Baia del Bottino⟧, dove ogni settimana scegliamo il miglior pescatore, che diventa il Maestro Pescatore!\n\nTra le due e le quattro del pomeriggio, banchi di tastyfish compaiono lungo tutta la costa di Rovotorto. Se mentre peschi il tuo galleggiante finisce in un banco di tastyfish, pescherai qualcosa dal banco invece del solito pescato di Rovotorto.", "." },
  ["db125e891bb6460c"] = { "Sì, hai sentito bene, {class}: tutte le nostre raccolte sono complete e l'ultimo carico di materiale bellico dovrebbe arrivare a ⟦Silithus=Silitus⟧ entro $2113w giorni. Mi dicono che, quando tutto sarà radunato lì e le nostre truppe saranno pronte, qualcuno tra le fila di voi eroi suonerà il gong fuori da ⟦Ahn'Qiraj=Ahn'qiraj⟧, dopo aver già assemblato lo Scettro delle Sabbie Mutevoli per farlo. Spero che non dovremo aspettare troppo.", "." },
  ["db13e37d19041db9"] = { "Lascia perdere!", "." },
  ["db152bcd2f85b3f0"] = { "Ah, la bellezza di ⟦Shadowglen=Vallombra⟧ non smette mai di deliziare i miei sensi!", "." },
  ["db217d119cb80e03"] = { "Gloria al padrone!", "." },
  ["db2953791a0c19b7"] = { "Voi, marmaglia, al lavoro. La nave dev'essere finita presto.", "." },
  ["db2a17fd775a071d"] = { "Forse avremo un momento per riposare. Ma non mi arrenderò finché non avremo affrontato Vorsha!", "." },
  ["db2af5388656ed49"] = { "Il Tecno-Ricostituente sta venendo proprio bene. Mancano solo pochi ritocchi!", "." },
  ["db2e806f85e4922e"] = { "Una voce tonante rimbomba dalla pietra...\n\nSalute, comandante. Quali notizie di ⟦Silithus=Silitus⟧ porti ai Signori del Concilio?", "." },
  ["db30e7b7a9bb3987"] = { "Ah sì, mi aveva detto che un agente dell'High Order sarebbe arrivato presto a ⟦Stormwind=Roccavento⟧. Mi ha chiesto di preparare delle istruzioni per te.\n\n<Randal ti consegna un biglietto sigillato con cura.>\n\nQuesto dovrebbe darti tutte le informazioni che ti servono. Ti aspetta un bel viaggio, {name}. Ti auguro buona fortuna a nome di ⟦Stormwind=Roccavento⟧ e dell'⟦Alliance=Alleanza⟧.", "." },
  ["db3eb6e7dc0de197"] = { "Se mi dimostro all'altezza agli occhi di Saru, non avrà altra scelta che lasciarmi combattere per una delle sue figlie. Allora vedremo chi riderà.", "." },
  ["db441edfb311986e"] = { "HAKKAR VIVE!", "." },
  ["db46bc097b5255e6"] = { "{name} ha superato il Gauntlet! Tre urrà per {name}!", "." },
  ["db4d536dcb669fb9"] = { "La prossima volta che vedo uno di voi che non lavora, farò tagliare la testa da Buzzer!", "." },
  ["db51d29cb9c8b47e"] = { "%s perde visibilmente forza. Felcurse sta facendo effetto!", "." },
  ["db57966fbb2a62b9"] = { "Cosa intendi?", "." },
  ["db5d4d314aa3594b"] = { "Keever non è contento di questo. Forse se Keever provasse una dose più grande, questo dilemma si risolverebbe.", "." },
  ["db6d44787758620f"] = { "Cassetta postale in mezzo a città, ⟦Trade Quarter=Quartiere del Commercio⟧, anello superiore... vicino a locanda.", "." },
  ["db719bc644ce808d"] = { "Per i nostri padroni!", "." },
  ["db7463fe03e38643"] = { "Ho sentito le loro risate di scherno mentre il mio grifone si schiantava in fiamme, {class}.\n\n«Slidore, puzzi!», gridavano.\n\nNessuno parla a Slidore in quel modo! Aiutami a uscire di qui, così posso mostrargli chi è il vero puzzone!", "." },
  ["db7e2321d72b6025"] = { "Non si tratta sempre di soldi, <pivello/pivella>! Anche se riceviamo donazioni generose, alcune davvero cospicue, la nostra compagnia itinerante di artisti trae la sua spinta creativa dal bisogno di rallegrare questo mondo devastato dalla guerra. Non preoccuparti per noi; lascia piuttosto che siamo noi a preoccuparci di come intrattenerti al meglio.", "." },
  ["db8164b391fe5d02"] = { "Noi piantiamo le verdure. Le nostre verdure le mangia il coniglio. Il coniglio lo divora il lupo. Il lupo lo uccidiamo noi. Prendiamo la carne e la pelle dal cadavere del lupo. È quel Magico Cerchio della vita, o come lo chiamate voi.\n\nOra va' da Telonis nell'⟦Cenarion Enclave=Enclave Cenariana⟧ per cominciare, e lasciami tornare ai miei doveri.", "." },
  ["db8aba657fab9239"] = { "La magia può ottenere quasi tutto, ma la stagnazione e l'inerzia ci hanno fatto perdere tanto di noi stessi nelle migliaia di anni trascorsi da quando abbiamo lasciato Kalimdor. L'High Order cerca di recuperare l'eredità degli ⟦Highborne=Alti Nobili⟧ che ci siamo lasciati alle spalle e di tornare padroni del nostro destino.\n\nI Windshaper ci considerano semplicemente sconsiderati e arroganti. Ipocrisia allo stato puro, se vuoi la mia opinione. I Windshaper non prendono in considerazione nessuna idea che non sia la loro, quando si tratta di questa crisi. Chi, mi chiedo, è davvero arrogante?", "." },
  ["db98df85afe29a23"] = { "Anche se l'esilio mi ha marchiato come eretico, le mie convinzioni restano vere: solo questo mi spinge avanti. Ma perché il mio destino si compia, mi serve l'aiuto di un estraneo... qualcuno che non appartenga a nessuna tribù di centauri.\n\nIl compito richiede che qualcuno entri nelle sacre sale di Maraudon, un tempio che il mio popolo protegge e in cui solo i più devoti possono entrare.\n\nSe accetti di aiutarmi, basta un cenno del capo. Ti passerò una pergamena con le mie istruzioni. Leggila e rifletti sulle mie parole.", "." },
  ["db9a5241d36518ea"] = { "Parla con Saru Steelfury al Burning Anvil. Vai nella ⟦Valley of Honor=Valle dell'Onore⟧. È alla fine del sentiero, a destra di Red Canyon Mining.", "." },
  ["dba5b728469bd357"] = { "Questa torta è buonissima, ne vuoi un po'?", "." },
  ["dbb3a62ce6e5e2bc"] = { "Cosa serve per il calderone alle Lacrime di Dalson?", "." },
  ["dbb6648b48d45c92"] = { "Chi controlla la West Frostwolf Tower?", "." },
  ["dbb70e9b233c496e"] = { "Voglio azzerare i miei talenti.", "." },
  ["dbbff4dda8a48e72"] = { "Offro le mie cavalcature solo a chi è considerato Osannato da Orgrimmar e dalla razza degli orchi. Va' a dimostrare il tuo valore, e metterò i miei possenti lupi a tua disposizione perché tu possa esaminarli.", "." },
  ["dbc4edbad44cb75d"] = { "Benvenut<o/a> alla ⟦Light's Hope Chapel=Cappella della Luce⟧, <straniero/straniera>.", "." },
  ["dbc73f5662086f89"] = { "Il potere dell'Occhio è indiscutibile, Ryson, ma che altro può fare?", "." },
  ["dbcc792fa468e632"] = { "Urrà, urrà! {name}! È fatta!", "." },
  ["dbd58d071c522c54"] = { "** SERVOMOTORI DISTRUTTI. PUNTAMENTO DELL'UNITÀ CORROTTO. SPEGNIMENTO IMMINENTE. **", "." },
  ["dbd6fae4be096a7a"] = { "Ci diffonderemo su tutta questa terra desolata!", "." },
  ["dbd8fe678d37dcb8"] = { "Non era mia intenzione coinvolgerti in questa storia, {name}. Ho passato ogni ora di veglia a guardarmi alle spalle da quando ho aiutato un vecchio amico in un'audace incursione nei ⟦Blackrock Spire=Bastioni di Roccianera⟧.", "." },
  ["dbe30170a6c540ea"] = { "Cosa dicono?", "." },
  ["dbe71f8293879b59"] = { "Accidenti! Due personalità focose. Litigherete spesso, ma il vostro amore brucerà altrettanto ardente!", "." },
  ["dbfc2fa811e3d040"] = { "Ti pagherò volentieri martedì per un hamburger oggi.", "." },
})
